import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getCourseForumTopics, createForumTopic } from '../../api';

export default function CourseForum() {
  const { courseId, courseTitle } = useParams();
  const [topics, setTopics] = useState([]);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [newTopic, setNewTopic] = useState({ title: '', content: '' });
  const [username, setUsername] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    loadTopics();
    getUserInfo();
  }, [courseId]);

  const loadTopics = async () => {
    try {
      const data = await getCourseForumTopics(courseId);
      setTopics(data);
    } catch (error) {
      console.error('Error loading topics:', error);
    }
  };

  const getUserInfo = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch('http://localhost:8080/api/auth/profile', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (response.ok) {
        const data = await response.json();
        setUsername(data.username);
      }
    } catch (error) {
      console.error('Error getting user info:', error);
    }
  };

  const handleCreateTopic = async (e) => {
    e.preventDefault();
    try {
      await createForumTopic({
        ...newTopic,
        courseId,
        author: username
      });
      setNewTopic({ title: '', content: '' });
      setShowCreateForm(false);
      loadTopics();
    } catch (error) {
      console.error('Error creating topic:', error);
    }
  };

  return (
    <div className="course-forum">
      <div className="forum-header">
        <button onClick={() => navigate('/forums')} className="back-btn">← Back to Forums</button>
        <h1>{courseTitle} Forum</h1>
        <button 
          onClick={() => setShowCreateForm(!showCreateForm)}
          className="create-topic-btn"
        >
          New Topic
        </button>
      </div>

      {showCreateForm && (
        <div className="create-topic-form">
          <form onSubmit={handleCreateTopic}>
            <input
              type="text"
              placeholder="Topic title"
              value={newTopic.title}
              onChange={(e) => setNewTopic({...newTopic, title: e.target.value})}
              required
            />
            <textarea
              placeholder="What would you like to discuss?"
              value={newTopic.content}
              onChange={(e) => setNewTopic({...newTopic, content: e.target.value})}
              required
            />
            <div className="form-actions">
              <button type="submit">Create Topic</button>
              <button type="button" onClick={() => setShowCreateForm(false)}>Cancel</button>
            </div>
          </form>
        </div>
      )}

      <div className="topics-list">
        {topics.map(topic => (
          <div key={topic.id} className="topic-card">
            <div className="topic-info">
              <h3 onClick={() => navigate(`/forums/topic/${topic.id}`)}>
                {topic.title}
              </h3>
              <p>Started by {topic.author} • {topic.replies} replies</p>
              <span>{new Date(topic.createdAt).toLocaleDateString()}</span>
            </div>
            <div className="topic-stats">
              <div className="replies-count">{topic.replies}</div>
              <div className="replies-label">replies</div>
            </div>
          </div>
        ))}
        {topics.length === 0 && (
          <div className="no-topics">
            <p>No discussions yet. Be the first to start a topic!</p>
          </div>
        )}
      </div>
    </div>
  );
}
